#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
        std::cin >> b[i];
    }

    int total_win = 0;
    std::vector<int> b_extended = b;
    b_extended.push_back(b[0]);
    for (int i = 0; i < 3; ++i) {
        total_win += std::min(a[i], b_extended[i + 1]);
    }
    b_extended.pop_back();
    b.insert(b.begin(), b[2]);

    for (int i = 0; i < 3; ++i) {
        if (a[i] > 0) {
            int d = std::min(a[i], b[i]);
            a[i] -= d;
            b[i] -= d;
            if (a[i] > 0) {
                int d2 = std::min(a[i], b[i + 1]);
                a[i] -= d2;
                b[i + 1] -= d2;
            }
        }
    }

    std::cout << a[0] + a[1] + a[2] << " " << total_win << std::endl;

    return 0;
}
